"""Checkpoint — 检查点持久化与崩溃恢复。

参考 Omnigent 的 Checkpoint 设计：
- 每个子任务执行后自动保存检查点到 SQLite
- 崩溃恢复：从最后成功的检查点继续执行
- 支持手动回滚到指定检查点

检查点状态机：
  pending → running → checkpoint_saved → done
                    ↘ failed → retry → running
"""
import json
import logging
from datetime import datetime

logger = logging.getLogger("agent.orchestration.checkpoint")


class CheckpointManager:
    """检查点管理器 — 持久化任务执行状态到 SQLite。"""

    def __init__(self, db):
        """
        参数:
            db: Database 实例
        """
        self.db = db

    def save(self, plan):
        """保存当前任务计划的检查点。

        在每个子任务执行完成后调用，持久化整个计划的状态。
        """
        state = {
            'plan_id': plan.plan_id,
            'original_message': plan.original_message,
            'final_synthesis': plan.final_synthesis,
            'subtasks': [t.to_dict() for t in plan.subtasks],
            'saved_at': datetime.now().isoformat(),
        }
        self.db.save_checkpoint(plan.plan_id, state)
        logger.info('检查点已保存: %s (子任务 %d 个)',
                    plan.plan_id, len(plan.subtasks))

    def load(self, plan_id):
        """加载任务计划的检查点。

        返回:
            TaskPlan 实例或 None（无检查点）
        """
        from agent_runtime.orchestration.decomposer import TaskPlan

        data = self.db.load_checkpoint(plan_id)
        if data is None:
            return None

        state = data.get('state')
        if not state:
            return None

        plan = TaskPlan.from_dict(state)
        logger.info('检查点已加载: %s (子任务 %d 个, %d 个已完成)',
                    plan.plan_id, len(plan.subtasks),
                    sum(1 for t in plan.subtasks if t.status == 'done'))
        return plan

    def delete(self, plan_id):
        """删除已完成的检查点。"""
        self.db.delete_checkpoint(plan_id)
        logger.info('检查点已删除: %s', plan_id)

    def get_resume_point(self, plan):
        """获取恢复执行的起点。

        返回需要继续执行的子任务列表（跳过已完成的）。
        """
        ready = []
        for t in plan.subtasks:
            if t.status in ('done', 'skipped'):
                continue
            if t.status == 'pending':
                # 检查依赖是否已满足
                done_ids = {st.id for st in plan.subtasks
                            if st.status == 'done'}
                if all(dep in done_ids for dep in t.depends_on):
                    ready.append(t)
        return ready

    def has_checkpoint(self, plan_id):
        """检查是否存在检查点。"""
        return self.db.load_checkpoint(plan_id) is not None

